import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import * as ImagePicker from "expo-image-picker";
import { useEffect, useState } from "react";
import { ActivityIndicator, Alert, Image, ScrollView, StyleSheet, Switch, Text, TextInput, TouchableOpacity, View } from "react-native";
import { router } from "expo-router";
import { ScreenContainer } from "@/components/screen-container";
import { djangoApi } from "@/lib/django-api";

const TYPES = [
  { id:"hero",label:"الرئيسية",icon:"view-carousel" }, { id:"banner",label:"بانر",icon:"image" },
  { id:"category",label:"فئات",icon:"category" }, { id:"product_grid",label:"منتجات",icon:"grid-view" }, { id:"trend",label:"ترند",icon:"trending-up" },
] as const;
type SectionType=typeof TYPES[number]["id"];
type Item=Record<string,any>;
type Section={id:number;title:string;section_type:SectionType;config:Item;sort_order:number;is_visible:boolean};
type Category={id:number;name:string;slug:string;parent?:number|null;image?:string|null};

export default function VendorStorefrontScreen(){
 const [sections,setSections]=useState<Section[]>([]);const [categories,setCategories]=useState<Category[]>([]);const [selected,setSelected]=useState<number|null>(null);const [draft,setDraft]=useState<Item>({});const [loading,setLoading]=useState(true);const [saving,setSaving]=useState(false);
 async function load(){try{setLoading(true);const [s,c]=await Promise.all([djangoApi<{results?:Section[]}>("/api/storefront-sections/"),djangoApi<{results?:Category[]}>("/api/categories/")]);setSections((s.results??[]).sort((a,b)=>a.sort_order-b.sort_order));setCategories(c.results??[])}catch(error){Alert.alert("تعذر تحميل محرر المتجر",error instanceof Error?error.message:"حاول مرة أخرى.")}finally{setLoading(false)}}
 useEffect(()=>{load()},[]);
 function edit(section:Section){setSelected(section.id);setDraft({...section.config,title:section.title,section_type:section.section_type,is_visible:section.is_visible})}
 async function create(type:SectionType){try{const config=type==="category"?{published:true,mode:"automatic",category_circles:[]}:type==="product_grid"||type==="trend"?{published:true,source:type==="trend"?"trending":"latest",rows:2,columns:2,scroll:true,show_categories:false}:{published:true,slides:[]};const created=await djangoApi<Section>("/api/storefront-sections/",{method:"POST",body:JSON.stringify({title:type==="product_grid"?"منتجات مختارة":type==="category"?"الفئات":"عرض جديد",section_type:type,config,sort_order:sections.length,is_visible:true})});setSections(v=>[...v,created].sort((a,b)=>a.sort_order-b.sort_order));edit(created)}catch(error){Alert.alert("تعذر إنشاء القسم",error instanceof Error?error.message:"حاول مرة أخرى.")}}
 async function remove(id:number){Alert.alert("حذف القسم","سيتم إزالة هذا القسم من واجهة المتجر. البيانات الأخرى لا تتأثر.",[{text:"إلغاء",style:"cancel"},{text:"حذف",style:"destructive",onPress:async()=>{try{await djangoApi(`/api/storefront-sections/${id}/`,{method:"DELETE"});setSections(v=>v.filter(x=>x.id!==id));if(selected===id){setSelected(null);setDraft({})}}catch(error){Alert.alert("تعذر الحذف",error instanceof Error?error.message:"تحقق من صلاحيات التاجر.")}}}])}
 async function chooseImage(){const r=await ImagePicker.launchImageLibraryAsync({mediaTypes:["images"],allowsEditing:false,quality:.82,base64:true});const a=r.assets?.[0];return !r.canceled&&a?.base64?`data:${a.mimeType??"image/jpeg"};base64,${a.base64}`:""}
 async function addBanner(){if(selected==null)return;const imageUrl=await chooseImage();if(!imageUrl)return;const slides=Array.isArray(draft.slides)?draft.slides:[];setDraft(d=>({...d,slides:[...slides,{id:`${selected}-${Date.now()}`,title:String(d.title??""),subtitle:"",ctaLabel:"تسوّق الآن",url:"",imageUrl,visible:true,sortOrder:slides.length}]}))}
 async function addCircle(){if(selected==null||!categories.length)return Alert.alert("لا توجد فئات","أضف الفئات من إدارة الكتالوج أولًا.");const choices=categories.slice(0,8).map(category=>({text:category.name,onPress:async()=>{const imageUrl=await chooseImage();if(!imageUrl)return;const circles=Array.isArray(draft.category_circles)?draft.category_circles:[];setDraft(d=>({...d,category_circles:[...circles,{id:`custom-${Date.now()}`,category_id:category.id,title:category.name,targetCategory:category.slug,url:`/collection?category=${encodeURIComponent(category.slug)}`,imageUrl,visible:true,sortOrder:circles.length}]}))}}));Alert.alert("اختر الفئة","ثم اختر صورة لها.",choices)}
 async function save(){if(selected==null)return;setSaving(true);try{const payload={title:String(draft.title??""),section_type:draft.section_type,is_visible:Boolean(draft.is_visible),config:Object.fromEntries(Object.entries(draft).filter(([k])=>!["title","section_type","is_visible"].includes(k)))};const updated=await djangoApi<Section>(`/api/storefront-sections/${selected}/`,{method:"PATCH",body:JSON.stringify(payload)});setSections(v=>v.map(x=>x.id===updated.id?updated:x));Alert.alert("تم الحفظ","تم حفظ تصميم المتجر والصور.")}catch(error){Alert.alert("تعذر الحفظ",error instanceof Error?error.message:"تحقق من الصور والبيانات.")}finally{setSaving(false)}}
 async function move(id:number,dir:-1|1){const ordered=[...sections].sort((a,b)=>a.sort_order-b.sort_order);const i=ordered.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=ordered.length)return;[ordered[i],ordered[j]]=[ordered[j],ordered[i]];try{for(let n=0;n<ordered.length;n++)await djangoApi(`/api/storefront-sections/${ordered[n].id}/`,{method:"PATCH",body:JSON.stringify({sort_order:n})});setSections(ordered.map((x,n)=>({...x,sort_order:n})))}catch(error){Alert.alert("تعذر الترتيب",error instanceof Error?error.message:"حاول مرة أخرى.")}}
 if(loading)return <ScreenContainer><View style={styles.center}><ActivityIndicator color="#E60023"/><Text style={styles.muted}>جارٍ تحميل محرر المتجر...</Text></View></ScreenContainer>;
 const current=selected!=null?sections.find(x=>x.id===selected):null;const slides=Array.isArray(draft.slides)?draft.slides:[];const circles=Array.isArray(draft.category_circles)?draft.category_circles:[];
 return <ScreenContainer className="bg-[#F5F6F8]" edges={["top","bottom","left","right"]}><View style={styles.header}><TouchableOpacity onPress={()=>router.back()}><MaterialIcons name="arrow-forward" size={24} color="#111"/></TouchableOpacity><View style={styles.headerCopy}><Text style={styles.headerTitle}>تصميم واجهة المتجر</Text><Text style={styles.headerSub}>إضافة، حذف، ترتيب، صور وبنرات</Text></View><TouchableOpacity style={styles.addButton} onPress={()=>create("banner")}><MaterialIcons name="add" size={22} color="#FFF"/></TouchableOpacity></View><ScrollView style={{flex:1}} contentContainerStyle={styles.page}><View style={styles.quick}><Text style={styles.heading}>إضافة قسم جديد</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.row}>{TYPES.map(t=><TouchableOpacity key={t.id} style={styles.quickBtn} onPress={()=>create(t.id)}><MaterialIcons name={t.icon as any} size={18} color="#111"/><Text style={styles.quickText}>{t.label}</Text></TouchableOpacity>)}</ScrollView></View><View style={styles.listCard}><Text style={styles.heading}>أقسام المتجر</Text>{sections.map((s,i)=><View key={s.id} style={[styles.sectionCard,selected===s.id&&styles.selected]}><TouchableOpacity style={styles.sectionTop} onPress={()=>edit(s)}><View style={styles.typeIcon}><MaterialIcons name={(TYPES.find(t=>t.id===s.section_type)?.icon??"view-module") as any} size={20} color="#168451"/></View><View style={styles.copy}><Text style={styles.sectionTitle}>{s.title||"قسم بدون عنوان"}</Text><Text style={styles.meta}>{TYPES.find(t=>t.id===s.section_type)?.label??s.section_type} · الموضع {i+1}</Text></View></TouchableOpacity><View style={styles.actions}><TouchableOpacity disabled={i===0} onPress={()=>move(s.id,-1)}><MaterialIcons name="keyboard-arrow-up" size={24} color={i===0?"#DDD":"#333"}/></TouchableOpacity><TouchableOpacity disabled={i===sections.length-1} onPress={()=>move(s.id,1)}><MaterialIcons name="keyboard-arrow-down" size={24} color={i===sections.length-1?"#DDD":"#333"}/></TouchableOpacity><Switch value={s.is_visible} onValueChange={v=>{setSections(xs=>xs.map(x=>x.id===s.id?{...x,is_visible:v}:x));djangoApi(`/api/storefront-sections/${s.id}/`,{method:"PATCH",body:JSON.stringify({is_visible:v})}).catch(()=>load())}}/><TouchableOpacity onPress={()=>remove(s.id)}><MaterialIcons name="delete-outline" size={22} color="#D11"/></TouchableOpacity></View></View>)}</View>{current?<View style={styles.editor}><Text style={styles.heading}>تحرير: {current.title}</Text><TextInput value={String(draft.title??"")} onChangeText={v=>setDraft(d=>({...d,title:v}))} style={styles.input} textAlign="right" placeholder="عنوان القسم"/><View style={styles.toggle}><Text>ظاهر للعملاء</Text><Switch value={Boolean(draft.is_visible)} onValueChange={v=>setDraft(d=>({...d,is_visible:v}))}/></View>{current.section_type==="category"?<><TouchableOpacity style={styles.mediaButton} onPress={addCircle}><MaterialIcons name="add-photo-alternate" size={21} color="#E60023"/><Text style={styles.mediaText}>إضافة فئة وصورة</Text></TouchableOpacity>{circles.map((c,i)=><View key={String(c.id)} style={styles.mediaItem}>{c.imageUrl?<Image source={{uri:String(c.imageUrl)}} style={styles.thumb}/>:<View style={styles.thumb}/>}<View style={styles.copy}><Text style={styles.sectionTitle}>{String(c.title??"")}</Text><TouchableOpacity onPress={()=>setDraft(d=>({...d,category_circles:(d.category_circles??[]).filter((_:Item,index:number)=>index!==i)}))}><Text style={styles.deleteText}>حذف</Text></TouchableOpacity></View></View>)}</>:null}{current.section_type==="hero"||current.section_type==="banner"?<><TouchableOpacity style={styles.mediaButton} onPress={addBanner}><MaterialIcons name="add-photo-alternate" size={21} color="#E60023"/><Text style={styles.mediaText}>إضافة صورة/بانر جديد</Text></TouchableOpacity>{slides.map((slide,i)=><View key={String(slide.id)} style={styles.mediaItem}>{slide.imageUrl?<Image source={{uri:String(slide.imageUrl)}} style={styles.bannerThumb}/>:<View style={styles.bannerThumb}/>}<View style={styles.copy}><TextInput value={String(slide.title??"")} onChangeText={v=>setDraft(d=>({...d,slides:(d.slides??[]).map((x:Item,n:number)=>n===i?{...x,title:v}:x)}))} style={styles.smallInput} textAlign="right" placeholder="عنوان البانر"/><TouchableOpacity onPress={()=>setDraft(d=>({...d,slides:(d.slides??[]).filter((_:Item,n:number)=>n!==i)}))}><Text style={styles.deleteText}>حذف البانر</Text></TouchableOpacity></View></View>)}</>:null}{current.section_type==="product_grid"||current.section_type==="trend"?<><Text style={styles.label}>مصدر المنتجات</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.row}>{["latest","trending","category"].map(v=><TouchableOpacity key={v} onPress={()=>setDraft(d=>({...d,source:current.section_type==="trend"?"trending":v}))} style={[styles.choice,draft.source===v&&styles.activeChoice]}><Text style={draft.source===v?styles.activeChoiceText:styles.choiceText}>{v==="latest"?"الأحدث":v==="trending"?"الترند":"حسب الفئة"}</Text></TouchableOpacity>)}</ScrollView>{draft.source==="category"&&current.section_type!=="trend"?<ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.row}>{categories.map(c=><TouchableOpacity key={c.id} onPress={()=>setDraft(d=>({...d,category_id:c.id}))} style={[styles.choice,String(draft.category_id)===String(c.id)&&styles.activeChoice]}><Text style={String(draft.category_id)===String(c.id)?styles.activeChoiceText:styles.choiceText}>{c.name}</Text></TouchableOpacity>)}</ScrollView>:null}</>:null}<TouchableOpacity disabled={saving} style={styles.save} onPress={save}>{saving?<ActivityIndicator color="#FFF"/>:<Text style={styles.saveText}>حفظ ونشر التغييرات</Text>}</TouchableOpacity></View>:null}</ScrollView></ScreenContainer>
}
const styles=StyleSheet.create({header:{height:64,backgroundColor:"#FFF",paddingHorizontal:15,flexDirection:"row",alignItems:"center",justifyContent:"space-between",borderBottomWidth:1,borderColor:"#EDEDED"},headerCopy:{flex:1,alignItems:"flex-end",marginHorizontal:12},headerTitle:{fontSize:18,fontWeight:"900",color:"#111"},headerSub:{fontSize:10,color:"#888",marginTop:2},addButton:{width:38,height:38,borderRadius:19,backgroundColor:"#E60023",alignItems:"center",justifyContent:"center"},page:{padding:12,paddingBottom:160,maxWidth:960,width:"100%",alignSelf:"center"},quick:{backgroundColor:"#FFF",borderRadius:14,padding:12,marginBottom:12},listCard:{backgroundColor:"#FFF",borderRadius:14,padding:12,marginBottom:12},heading:{fontSize:15,fontWeight:"900",color:"#111",textAlign:"right",marginBottom:10},row:{gap:8,paddingBottom:5},quickBtn:{minWidth:100,paddingVertical:11,paddingHorizontal:12,borderRadius:11,backgroundColor:"#F7F7F8",borderWidth:1,borderColor:"#E5E5E5",alignItems:"center",gap:5},quickText:{fontSize:10,fontWeight:"800",color:"#222"},sectionCard:{backgroundColor:"#FFF",borderRadius:12,padding:10,borderWidth:1,borderColor:"#EEE",marginBottom:8},selected:{borderColor:"#111"},sectionTop:{flexDirection:"row-reverse",alignItems:"center",gap:10},typeIcon:{width:38,height:38,borderRadius:10,backgroundColor:"#F0F8F3",alignItems:"center",justifyContent:"center"},copy:{flex:1,alignItems:"flex-end"},sectionTitle:{fontSize:12,fontWeight:"900",color:"#222"},meta:{fontSize:9,color:"#888",marginTop:2},actions:{marginTop:8,flexDirection:"row-reverse",alignItems:"center",gap:10},editor:{backgroundColor:"#FFF",borderRadius:14,padding:14},input:{backgroundColor:"#F7F7F8",borderWidth:1,borderColor:"#E3E3E5",borderRadius:10,padding:11,fontSize:13,color:"#111",marginBottom:10},toggle:{flexDirection:"row-reverse",justifyContent:"space-between",alignItems:"center",padding:10,backgroundColor:"#F8F8F8",borderRadius:10,marginBottom:10},mediaButton:{height:46,borderWidth:1,borderColor:"#F0B3BA",backgroundColor:"#FFF7F8",borderRadius:10,flexDirection:"row-reverse",alignItems:"center",justifyContent:"center",gap:7,marginBottom:9},mediaText:{color:"#A6001D",fontWeight:"900",fontSize:11},mediaItem:{flexDirection:"row-reverse",gap:10,alignItems:"center",padding:9,borderWidth:1,borderColor:"#EEE",borderRadius:10,marginBottom:8},thumb:{width:55,height:55,borderRadius:9,backgroundColor:"#F0F0F0",overflow:"hidden"},bannerThumb:{width:85,height:55,borderRadius:9,backgroundColor:"#F0F0F0",overflow:"hidden"},smallInput:{backgroundColor:"#F7F7F8",borderRadius:8,padding:8,fontSize:11,color:"#111",marginBottom:6},deleteText:{color:"#D11",fontSize:10,fontWeight:"900"},label:{fontSize:11,fontWeight:"900",color:"#555",textAlign:"right",marginBottom:6},choice:{paddingHorizontal:13,paddingVertical:9,borderRadius:18,borderWidth:1,borderColor:"#DDD",backgroundColor:"#FFF"},choiceText:{fontSize:10,color:"#666",fontWeight:"800"},activeChoice:{backgroundColor:"#111",borderColor:"#111"},activeChoiceText:{fontSize:10,color:"#FFF",fontWeight:"800"},save:{height:48,backgroundColor:"#E60023",borderRadius:12,alignItems:"center",justifyContent:"center",marginTop:8},saveText:{color:"#FFF",fontWeight:"900",fontSize:13},center:{flex:1,alignItems:"center",justifyContent:"center",gap:9},muted:{color:"#777",fontSize:12}});
